// #b24fab ניהול חשבון ארגוני ומשתמשים — имя из регистрации сохраняется и видно в /users; ссылка-приглашение.
// Обновлено 15.11.2026 под новое поведение (не баги продукта): ссылка в баннере теперь только `/accept?token=` (#83bf5b —
// данные приглашения берутся по токену, не из адреса); «ביטול הזמנה» — через окно подтверждения «ביטול ההזמנה» (#db7e39).
// Кейсы: .qa/tests/org-account/OA-01, OA-02 (OA-M1 — только вручную). План: specs/org-account.md.
// Роль NEWADMIN — מנהל חשבון компании «test», зарегистрирован пользователем 10.11.2026 (full_name «test test»).
// Сессия .qa/auth/newadmin.json; в accounts.env её логина нет — обновлять: npm run qa-login:manual -- newadmin.
// Нет файла сессии → тесты пропускаются с подсказкой (не падают).
import { test, expect, Page } from '@playwright/test';
import * as fs from 'fs';
import { authState } from '../helpers/tenderflow';
import { openUsers, readRows } from '../company-users/users-page';
import { cancelAllInvites, invite, readBannerLink } from '../helpers/invites';

const NEWADMIN = authState('newadmin');
const FULL_NAME = 'test test';
const INVITEE = 'QA-AUTO Org Invite';

test.skip(!fs.existsSync(NEWADMIN), 'Нет сессии newadmin (.qa/auth/newadmin.json) — npm run qa-login:manual -- newadmin');
test.use({ storageState: NEWADMIN });

const qaEmail = () => `qa-auto-org-${Date.now()}-${Math.floor(Math.random() * 1000)}@example.com`;
const qaRows = (page: Page) => page.getByRole('row').filter({ hasText: /qa-auto-org-/ });

/** Отменить (с подтверждением) все приглашения qa-auto-org-… (в т.ч. оставшиеся от упавших прогонов). */
const cleanup = (page: Page) => cancelAllInvites(page, /qa-auto-org-/);

test.describe('חשבון ארגוני — NEWADMIN', () => {
  test('שם מההרשמה נשמר: ב-/users בעמודת שם מוצג "test test" (מנהל חשבון, פעיל) #b24fab @desktop @prod-safe', async ({ page }) => {
    // OA-01: только чтение.
    await openUsers(page);
    const rows = await readRows(page);
    const me = rows.find((r) => r.name === FULL_NAME);
    expect(me, `в /users нет строки с именем «${FULL_NAME}»: ${JSON.stringify(rows)}`).toBeTruthy();
    expect(me).toMatchObject({ role: 'מנהל חשבון', status: 'פעיל' });
    expect(me!.email).toMatch(/^[^\s@]+@[^\s@]+\.[^\s@]+$/);
    // Имя не пустое ни у одного активного участника (раньше было «—»).
    for (const r of rows.filter((x) => x.status === 'פעיל')) expect(r.name, `имя у ${r.email}`).not.toMatch(/^(—|-|)$/);
  });

  test('קישור ההזמנה בבאנר מכיל רק token (בלי inviter/email בכתובת) #b24fab @desktop @data', async ({ page }) => {
    // OA-02 (обновлён 15.11): создаётся приглашение qa-auto-org-…@example.com и отменяется в finally.
    // Раньше ожидали inviter=«test test» и email в ссылке; после #83bf5b ссылка — только token.
    const email = qaEmail();
    try {
      await invite(page, INVITEE, email);
      const link = await readBannerLink(page);
      const params = new URL(link).searchParams;
      expect(params.get('token'), 'token').toMatch(/^[0-9a-f]{32,}$/i);
      expect([...params.keys()], 'в ссылке только token').toEqual(['token']);
    } finally {
      await cleanup(page);
    }
    await expect(qaRows(page)).toHaveCount(0);
  });
});
